head.script:
/*
 * ===========================================================================
 * [재현 시나리오] gridView 푸터 다중 셀 복사 시 컬럼 이동 순서 미반영
 * ---------------------------------------------------------------------------
 * 1) 페이지 로드 후, gridView의 헤더를 드래그하여 컬럼 위치를 임의로 이동
 *    (예: "name1" 컬럼을 "name3" 위치로 이동)
 *    → 푸터도 화면상 함께 이동되는 것을 확인 (columnMoveWithFooter="true")
 *
 * 2) [정상 케이스] 본문(body) 영역에서 좌우로 연속된 셀 2개 이상을 드래그 선택
 *    → Ctrl+C 후 메모장/엑셀에 Ctrl+V
 *    → 화면에 보이는 이동된 컬럼 순서대로 정상 출력됨
 *
 * 3) [버그 케이스] 푸터(footer) 영역에서 좌우로 연속된 셀 2개 이상을 드래그 선택
 *    → Ctrl+C 후 메모장/엑셀에 Ctrl+V
 *    → 컬럼 이동 전(원본) 순서로 출력됨 (현상 발생)
 *
 * 4) [참고: 정상 케이스]
 *    - 푸터 단일 셀 선택 후 복사 → 정상
 *    - 푸터 셀 안 텍스트만 글자 드래그 후 복사 → 정상 (네이티브 oncopy 경로)
 *
 * [핵심 속성]
 *  - columnMove="true"            : 컬럼 드래그앤드롭 이동 허용
 *  - columnMoveWithFooter="true"  : 컬럼 이동 시 푸터도 함께 이동
 *  - focusFooter="true"           : 푸터 셀 선택 가능 상태 활성화 (깡통 재현용)
 * ===========================================================================
 */

scwin.onpageload = function () {

	var tmpJSON = [
		{ "col1": "행1-1", "col2": "행1-2", "col3": "행1-3", "col4": 11, "col5": 12, "col6": 13 },
		{ "col1": "행2-1", "col2": "행2-2", "col3": "행2-3", "col4": 21, "col5": 22, "col6": 23 },
		{ "col1": "행3-1", "col2": "행3-2", "col3": "행3-3", "col4": 31, "col5": 32, "col6": 33 },
		{ "col1": "행4-1", "col2": "행4-2", "col3": "행4-3", "col4": 41, "col5": 42, "col6": 43 },
		{ "col1": "행5-1", "col2": "행5-2", "col3": "행5-3", "col4": 51, "col5": 52, "col6": 53 }
	];
	dataList1.setJSON(tmpJSON);

	// 푸터에 컬럼별로 다른 값을 세팅하여 복사 결과의 컬럼 순서를 명확히 식별 가능하게 함
	gridView1.setFooterData("col1", "푸터-A");
	gridView1.setFooterData("col2", "푸터-B");
	gridView1.setFooterData("col3", "푸터-C");
	gridView1.setFooterData("col4", "푸터-D");
	gridView1.setFooterData("col5", "푸터-E");
	gridView1.setFooterData("col6", "푸터-F");
};

scwin.onpageunload = function () {

};

// 컬럼 이동 후 현재 컬럼 순서 확인용 (디버깅 편의)
scwin.trigger_checkOrder_onclick = function (e) {
	var order = gridView1.getColumnOrder();
	alert("현재 컬럼 순서: " + JSON.stringify(order));
};

// 프로그래밍 방식으로 컬럼 이동 (드래그앤드롭이 어려울 때 재현용)
scwin.trigger_moveColumn_onclick = function (e) {
	// col1 ↔ col3 위치 교환 시나리오
	gridView1.setColumnOrder(["col3", "col2", "col1", "col4", "col5", "col6"]);
};
